  SuggestionRequest copyWith({String? input, int? cursor, int? start, String? remaining, }) => SuggestionRequest(input: input ?? this.input, cursor: cursor ?? this.cursor, start: start ?? this.start, remaining: remaining ?? this.remaining, );
}
/// Generation phase for custom chunk generation.
enum GenerationPhase {
  biomes('biomes'),
  noise('noise'),
  surface('surface'),
  features('features');
  const GenerationPhase(this.wireName);
  /// The name of this case in the WIT (kebab-case).
  final String wireName;
  /// The case called [wireName] in the WIT, or `null` if there is none.
  static GenerationPhase? fromWireName(String wireName) => _byWireName[wireName];
  static final Map<String, GenerationPhase> _byWireName = {for (final value in values) value.wireName: value};
}
/// The world's exported functions. Implement this and pass an instance to
/// [definePlugin] from `main()`.
abstract interface class PluginExports {
/// --- Plugin-provided exports ---
/// Called by the host once to initialize the plugin.
/// Internal use only; plugins should use the `register_plugin!` macro.
/// This callback is synchronous and only wires up the plugin
/// Perform setup that needs to await host calls in `on-load`
void initPlugin();
/// Called when the plugin is being loaded.
/// Use this to register commands, events, and perform initial setup.
Future<i1.Result<void, String>> onLoad(Context context);
/// Called when the plugin is being unloaded.
/// Use this to save data and clean up resources.
Future<i1.Result<void, String>> onUnload(Context context);
/// Dispatches an event to the plugin and returns the updated event.
/// 
/// The event is transferred by value
/// For blocking handlers, the host applies supported changes from the returned event
/// For nonblocking handlers, the host ignores returned changes
/// If the returned variant case differs from the dispatched case, the host
/// treats the result as a handler error and keeps the original event.
Future<Event> handleEvent(int eventId, Server server, Event event);
/// Dispatches a command execution to the plugin.
Future<i1.Result<int, CommandError>> handleCommand(int commandId, CommandSender sender, Server server, ConsumedArgs args);
/// Dispatches a command suggestion request to the plugin.
Future<CommandSuggestions> handleCommandSuggestion(int handlerId, CommandSender sender, Server server, SuggestionRequest request);
/// Dispatches a scheduled task execution to the plugin.
Future<void> handleTask(int handlerId, Server server);
/// Processes an incoming message from another plugin if possible, and returns (a possibly empty) response.
Future<i1.Result<List<int>, String>> handleIpcMessage(String sender, List<int> message);
/// Checks whether an AI goal can start.
Future<bool> handleAiGoalCanStart(int goalId, Server server, Entity entity);
/// Checks whether an active AI goal should continue.
Future<bool> handleAiGoalShouldContinue(int goalId, Server server, Entity entity);
/// Starts an AI goal.
Future<void> handleAiGoalStart(int goalId, Server server, Entity entity);
/// Runs one tick of an active AI goal.
Future<void> handleAiGoalTick(int goalId, Server server, Entity entity);
/// Stops an AI goal.
Future<void> handleAiGoalStop(int goalId, Server server, Entity entity);
/// Dispatches a chunk generation phase to the plugin.
Future<void> handleGeneratePhase(int generatorId, GenerationPhase phase, ChunkBuffer chunk);
}
late PluginExports _worldExports;
final class PluginMetadata {
/// Name of the plugin.
  final String name;
/// Plugin version (semver).
  final String version;
/// Plugin authors.
  final List<String> authors;
/// Short description of the plugin.
  final String description;
/// Plugin dependencies.
  final List<String> dependencies;
/// Permissions requested by the plugin.
  final List<String> permissions;
  const PluginMetadata({required this.name, required this.version, required this.authors, required this.description, required this.dependencies, required this.permissions, });
  PluginMetadata copyWith({String? name, String? version, List<String>? authors, String? description, List<String>? dependencies, List<String>? permissions, }) => PluginMetadata(name: name ?? this.name, version: version ?? this.version, authors: authors ?? this.authors, description: description ?? this.description, dependencies: dependencies ?? this.dependencies, permissions: permissions ?? this.permissions, );
}
/// Plugin metadata describing the plugin and its compatibility.
abstract interface class Metadata {
/// Returns a snapshot of the plugin's metadata
/// 
/// This callback must not call host imports or perform I/O
PluginMetadata getMetadata();
}
late Metadata _metadata;
